import { MakeLogicType, actions, afterMount, beforeUnmount, connect, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { preflightLogic } from 'scenes/PreflightCheck/preflightLogic'

import { PreflightStatus } from '~/types'

import { type VerifyEmailReason, verifyEmailLogic } from './verifyEmailLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface verifyEmailTelemetryLogicValues {
    preflight: PreflightStatus | null // preflightLogic
    reason: VerifyEmailReason | null // verifyEmailLogic
    verificationEmailSent: boolean // verifyEmailLogic
    failedAttempts: number
    helpOpened: boolean
    resends: number
    verified: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface verifyEmailTelemetryLogicActions {
    reportHelpOpened: () => {
        value: true
    }
}

export type verifyEmailTelemetryLogicType = MakeLogicType<
    verifyEmailTelemetryLogicValues,
    verifyEmailTelemetryLogicActions
>

/**
 * Every event that sizes the email verification funnel is emitted here, and nowhere else.
 *
 * The page is a hard gate on signup, so the counts that matter are how many people arrive, how many
 * verify, and what the ones who never verify did first. `email verification page viewed` is the
 * denominator, because the send event comes from a Celery task that cannot see whether the person
 * ever reached the page. The exit event closes the funnel. Its properties say whether the person
 * asked for another code or opened the help before they gave up, which separates a mistyped code
 * from mail that never arrived.
 */
export const verifyEmailTelemetryLogic = kea<verifyEmailTelemetryLogicType>([
    path(['scenes', 'authentication', 'verify-email', 'verifyEmailTelemetryLogic']),
    connect(() => ({
        values: [preflightLogic, ['preflight'], verifyEmailLogic, ['reason', 'verificationEmailSent']],
    })),
    actions({
        reportHelpOpened: true,
    }),
    reducers(() => ({
        resends: [0, { [verifyEmailLogic.actionTypes.requestVerificationCode]: (state: number) => state + 1 }],
        failedAttempts: [
            0,
            {
                [verifyEmailLogic.actionTypes.setVerificationCodeError]: (
                    state: number,
                    { error }: { error: string | null }
                ) => (error ? state + 1 : state),
            },
        ],
        helpOpened: [false, { reportHelpOpened: () => true }],
        verified: [
            false,
            {
                [verifyEmailLogic.actionTypes.submitVerificationCodeSuccess]: (
                    state: boolean,
                    { verificationResult }: { verificationResult: { success: boolean } | null }
                ) => state || !!verificationResult?.success,
            },
        ],
    })),
    listeners(({ values }) => ({
        [verifyEmailLogic.actionTypes.requestVerificationCodeSuccess]: ({
            newlyRequestedVerificationCode,
        }: {
            newlyRequestedVerificationCode: boolean
        }) => {
            posthog.capture('email verification code resent', {
                sent: newlyRequestedVerificationCode,
                region: values.preflight?.region,
            })
        },
        // Every rejected code lands here, whether the server refused it or the field never held six
        // digits. A cleared error is not an attempt, so the null case reports nothing.
        [verifyEmailLogic.actionTypes.setVerificationCodeError]: ({ error }: { error: string | null }) => {
            if (error) {
                posthog.capture('email verification failed', { region: values.preflight?.region })
            }
        },
        reportHelpOpened: () => {
            posthog.capture('email verification help opened', {
                resends: values.resends,
                failed_attempts: values.failedAttempts,
                region: values.preflight?.region,
            })
        },
    })),
    afterMount(({ values, cache }) => {
        posthog.capture('email verification page viewed', {
            // False when the send already failed before the redirect. That is a different stall
            // from mail that was sent and never arrived.
            code_sent: values.verificationEmailSent,
            deep_link_reason: values.reason,
            region: values.preflight?.region,
        })
        // Most people who give up close the tab, which unmounts nothing, so the exit needs both a
        // page-lifecycle hook and the unmount. `cache.exited` keeps whichever fires first the only
        // one that reports, and starts each mount over so a second visit reports its own exit.
        cache.exited = false
        cache.reportExit = (event?: PageTransitionEvent): void => {
            // A `pagehide` into the back-forward cache suspends the page rather than ending the
            // visit. Reporting it would call a person who comes back and verifies an abandonment.
            if (event?.persisted || cache.exited) {
                return
            }
            cache.exited = true
            posthog.capture('email verification exited', {
                outcome: values.verified ? 'verified' : 'left',
                resends: values.resends,
                failed_attempts: values.failedAttempts,
                help_opened: values.helpOpened,
                region: values.preflight?.region,
            })
        }
        cache.disposables.add(
            () => {
                window.addEventListener('pagehide', cache.reportExit)
                return () => window.removeEventListener('pagehide', cache.reportExit)
            },
            'pagehide',
            // The listener has to survive the hide it reports on, so it cannot pause with the page.
            { pauseOnPageHidden: false }
        )
    }),
    beforeUnmount(({ cache }) => {
        cache.reportExit()
    }),
])
